// Free RSS feeds for UFC/MMA news. A source works only if article images can be fetched remotely.
const feeds = [
	{ name: 'UFC.com', url: 'https://www.ufc.com/rss/news', allUfc: true },
	{ name: 'ESPN MMA', url: 'https://www.espn.com/espn/rss/mma/news' },
	{ name: 'MMA Fighting', url: 'https://www.mmafighting.com/rss/index.xml' },
	{ name: 'Sherdog', url: 'https://www.sherdog.com/rss/news.xml' },
	{ name: 'MMA News', url: 'https://www.mmanews.com/feed' },
	{ name: 'BJPenn.com', url: 'https://bjpenn.com/feed/' },
	{ name: 'LowKick MMA', url: 'https://www.lowkickmma.com/feed/' },
	{ name: 'Cageside Press', url: 'https://www.cagesidepress.com/feed' },
];

return feeds.map((feed) => ({ json: feed }));

// Pick the newest UFC stories that this workflow has not posted or skipped yet.
const settings = $('Settings').first().json;
const feeds = $('News sources').all().map((item) => item.json);
const memory = $getWorkflowStaticData('global');
const seen = new Set([...(memory.postedKeys ?? []), ...(memory.skippedKeys ?? [])]);

const maxAgeMs = Number(settings.maxStoryAgeHours || 48) * 60 * 60 * 1000;
const candidateCount = 12;

const host = (url) => {
	try {
		return new URL(url).hostname.replace(/^www\./, '').toLowerCase();
	} catch {
		return '';
	}
};

const linkKey = (url) => {
	try {
		const parsed = new URL(url);
		return `link:${parsed.hostname.replace(/^www\./, '')}${parsed.pathname.replace(/\/+$/, '')}`.toLowerCase();
	} catch {
		return `link:${String(url).toLowerCase()}`;
	}
};

const titleKey = (title) =>
	`title:${String(title)
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, ' ')
		.trim()}`;

const firstUrl = (value) => {
	if (!value) return '';
	if (typeof value === 'string') return value;
	if (Array.isArray(value)) return firstUrl(value[0]);
	return value.url || value.$?.url || value.href || '';
};

const looksLikeImage = (url) => /\.(jpe?g|png|webp|gif|avif)(\?|$)/i.test(url);

const decodeUrl = (url) => String(url).replace(/&#0?38;|&amp;/g, '&');

function feedImage(item) {
	const enclosure = item.enclosure;
	if (enclosure?.url && (/^image\//.test(enclosure.type || '') || looksLikeImage(enclosure.url))) {
		return decodeUrl(enclosure.url);
	}
	const media = firstUrl(item['media:content']) || firstUrl(item['media:thumbnail']);
	if (media) return decodeUrl(media);
	const html = `${item['content:encoded'] || ''} ${item.content || ''}`;
	const img = html.match(/<img[^>]+src=["']([^"']+)["']/i);
	return img ? decodeUrl(img[1]) : '';
}

const feedForLink = (link) => {
	const linkHost = host(link);
	return feeds.find((feed) => {
		const feedHost = host(feed.url);
		return (
			linkHost === feedHost || linkHost.endsWith(`.${feedHost}`) || feedHost.endsWith(`.${linkHost}`)
		);
	});
};

const now = Date.now();
const stories = [];
const keysInThisRun = new Set();

for (const { json: item } of $('Read news feeds').all()) {
	if (item.error || !item.title || !item.link) continue;

	const published = new Date(item.isoDate || item.pubDate || 0).getTime();
	if (!published || now - published > maxAgeMs || published > now + 60 * 60 * 1000) continue;

	const feed = feedForLink(item.link);
	const categories = Array.isArray(item.categories) ? item.categories.join(' ') : '';
	const text = `${item.title} ${categories} ${item.contentSnippet || ''} ${item.link}`;
	const hasUfc =
		feed?.allUfc ||
		/(^|[^a-z])ufc([^a-z]|$)/i.test(text) ||
		/\bulimate fighting championship\b/i.test(text) ||
		/\bufc\s*\d{2,4}\b/i.test(text);
	if (!hasUfc) continue;

	const nonUfcSport =
		/\b(wrestling|real american freestyle|\braf\b|wwe|bare knuckle|nhra|nba\b|nfl\b|mlb\b|ncaa wrestling)\b/i.test(
			text,
		);
	if (!feed?.allUfc && nonUfcSport && !/(^|[^a-z])ufc([^a-z]|$)/i.test(text)) continue;

	const keys = [linkKey(item.link), titleKey(item.title)];
	if (keys.some((key) => seen.has(key) || keysInThisRun.has(key))) continue;
	keys.forEach((key) => keysInThisRun.add(key));

	stories.push({
		title: String(item.title).trim(),
		link: item.link,
		source: feed?.name || host(item.link),
		publishedAt: new Date(published).toISOString(),
		snippet: String(item.contentSnippet || item.content || '').slice(0, 2000),
		feedImage: feedImage(item),
		keys,
	});
}

stories.sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));

return stories.slice(0, candidateCount).map((story) => ({ json: story }));

// Build Instagram posts with Ollama captions and a bottom-right logo watermark.
const settings = $('Settings').first().json;
const stories = $('Pick new UFC stories').all();
const pages = $input.all();

const decode = (text) =>
	String(text)
		.replace(/&amp;|&#0?38;/g, '&')
		.replace(/&quot;/g, '"')
		.replace(/&#0?39;|&apos;/g, "'")
		.replace(/&#8217;/g, '’')
		.replace(/&#8216;/g, '‘')
		.replace(/&#8220;/g, '“')
		.replace(/&#8221;/g, '”')
		.replace(/&#8230;/g, '…')
		.replace(/&nbsp;/g, ' ')
		.replace(/&lt;/g, '<')
		.replace(/&gt;/g, '>');

function metaContent(html, names) {
	if (typeof html !== 'string') return '';
	for (const tag of html.match(/<meta\b[^>]*>/gi) || []) {
		const name = tag.match(/(?:property|name)\s*=\s*["']([^"']+)["']/i)?.[1]?.toLowerCase();
		if (!names.includes(name)) continue;
		const content = tag.match(/content\s*=\s*"([^"]*)"|content\s*=\s*'([^']*)'/i);
		const value = content?.[1] ?? content?.[2];
		if (value) return decode(value).trim();
	}
	return '';
}

function pageImage(html) {
	const url = metaContent(html, ['og:image', 'og:image:secure_url', 'twitter:image', 'twitter:image:src']);
	return /^https?:\/\//i.test(url) ? url : '';
}

const pageSummary = (html) => metaContent(html, ['og:description', 'description', 'twitter:description']);

function cleanSnippet(text) {
	return decode(text)
		.replace(/The post .* appeared first on .*$/is, '')
		.replace(/Read the Full Article Here/gi, '')
		.replace(/\b[A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+\d{1,2},?\s+\d{4}\b/g, '')
		.replace(/\s*\[(?:…|\.\.\.)\]\s*$/, '…')
		.replace(/\s+/g, ' ')
		.trim();
}

function polishCaption(raw, headline) {
	let text = String(raw || '').trim();
	const h = decode(headline).trim();
	if (h && text.toLowerCase().startsWith(h.toLowerCase())) {
		text = text.slice(h.length).replace(/^[\s.:;,-]+/, '').trim();
	}
	if (h && text.toLowerCase() === h.toLowerCase()) text = '';

	text = text
		.replace(/\b(it is important to note that|in conclusion|furthermore|moreover|additionally)\b/gi, '')
		.replace(/\b[A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+\d{1,2},?\s+\d{4}\b/g, '')
		.replace(/\n{3,}/g, '\n\n')
		.replace(/\s+/g, ' ')
		.trim();

	return text;
}

function shorten(text, max) {
	if (text.length <= max) return text;
	const cut = text.slice(0, max);
	return `${cut.slice(0, Math.max(cut.lastIndexOf(' '), max - 20)).trim()}…`;
}

function articleBody(html) {
	if (typeof html !== 'string') return '';
	const chunk =
		html.match(/<article[\s\S]*?<\/article>/i)?.[0] ||
		html.match(/<main[\s\S]*?<\/main>/i)?.[0] ||
		html;
	const text = chunk
		.replace(/<script[\s\S]*?<\/script>/gi, ' ')
		.replace(/<style[\s\S]*?<\/style>/gi, ' ')
		.replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
		.replace(/<[^>]+>/g, ' ')
		.replace(/\s+/g, ' ')
		.trim();
	return cleanSnippet(text);
}

function storyContext(story, html) {
	const parts = [
		cleanSnippet(pageSummary(html)),
		articleBody(html),
		cleanSnippet(story.snippet),
	].filter(Boolean);
	const merged = parts.join(' ').replace(/\s+/g, ' ').trim();
	return shorten(merged || decode(story.title), 1400);
}

function fallbackCaption(story, html) {
	const title = decode(story.title);
	const detail = shorten(storyContext(story, html), 650);
	return detail && detail !== title ? `${title}\n\n${detail}` : title;
}

function instagramImage(source) {
	let url = `https://images.weserv.nl/?url=${encodeURIComponent(source)}&w=1080&h=1080&fit=contain&cbg=000000&output=jpg&q=90`;
	const localLogo = String(settings.logoFilePath || '').trim();
	if (localLogo) return url;
	const logo = String(settings.logoPublicUrl || '').trim();
	if (!logo || logo.includes('PASTE_PUBLIC')) return url;
	const scale = Number(settings.logoMarkScale || 14);
	const pad = Number(settings.logoMarkPad || 22);
	return `${url}&mark=${encodeURIComponent(logo)}&markpos=bottom-right&markpad=${pad}&markscale=${scale}`;
}

async function ollamaCaption(story, html) {
	const base = String(settings.ollamaBaseUrl || 'http://127.0.0.1:11434').replace(/\/$/, '');
	const model = String(settings.ollamaModel || 'llama3.2');
	const context = storyContext(story, html);
	const published = story.publishedAt
		? new Date(story.publishedAt).toLocaleDateString('en-US', {
				month: 'long',
				day: 'numeric',
				year: 'numeric',
			})
		: '';
	const prompt = `You write UFC news captions for fight fans on social media. Sound human — not like a wire report or SEO article.

Headline (do NOT copy verbatim as your opening line): ${decode(story.title)}
Facts to use: ${context}
Outlet: ${story.source} (${published || 'recent'})

Style:
- Open with one punchy hook sentence (your own words).
- Then 1-2 short paragraphs, 70-110 words total.
- Mix short and medium sentences. Contractions are fine.
- Say what happened, who it affects, and why fans should care — only from the facts above.
- No author bylines, no publish dates, no outlet name in the body, no quote marks unless quoting exact words from the facts.
- No hashtags, emojis, bullet lists, or "link in bio".
- Do not mention Instagram or "caption".`;

	try {
		const res = await fetch(`${base}/api/generate`, {
			method: 'POST',
			headers: { 'Content-Type': 'application/json' },
			body: JSON.stringify({
				model,
				prompt,
				stream: false,
				options: { temperature: 0.88, num_predict: 300 },
			}),
			signal: AbortSignal.timeout(90000),
		});
		if (!res.ok) throw new Error(`ollama ${res.status}`);
		const data = await res.json();
		const text = polishCaption(String(data.response || '').trim(), story.title);
		return text || fallbackCaption(story, html);
	} catch {
		return fallbackCaption(story, html);
	}
}

return (async () => {
	const posts = [];
	for (let i = 0; i < stories.length; i++) {
		const story = stories[i].json;
		const html = pages[i]?.json?.data;
		const sourceImage = pageImage(html) || story.feedImage;
		if (!sourceImage) continue;

		const body = await ollamaCaption(story, html);
		const tags = String(settings.hashtags || '#ufc #mma #ufcnews #mixedmartialarts #fightnews')
			.toLowerCase()
			.trim();
		const footer = [`Source: ${story.source}`, `Full story: ${story.link}`, '', tags].join('\n').trim();
		const caption = shorten(body, 2200 - footer.length - 4) + `\n\n${footer}`;

		posts.push({
			json: {
				...story,
				sourceImage,
				imageUrl: instagramImage(sourceImage),
				caption,
			},
		});
	}
	return posts;
})();

// Choose the newest post whose image Instagram can load.
// Each failed Instagram attempt runs this node again, so run N takes the next working post.
const posts = $('Build Instagram posts').all();
const checks = $('Check images').all();

const working = posts.filter((post, i) => {
  const check = checks[i]?.json ?? {};
  const type = String(check.headers?.['content-type'] ?? '');
  return check.statusCode === 200 && type.startsWith('image/jpeg');
});

const post = working[$runIndex];
return post ? [{ json: post.json }] : [];

// Remember the story, so a later run never posts it again.
const post = $('Choose story to post').first().json;
const memory = $getWorkflowStaticData('global');
memory.postedKeys = [...(memory.postedKeys ?? []), ...post.keys].slice(-2000);

return [
  {
    json: {
      posted: true,
      instagramMediaId: $json.id,
      title: post.title,
      link: post.link,
      postedAt: new Date().toISOString(),
    },
  },
];

// Instagram rejected this story. Do not try it again on a later day.
const post = $('Choose story to post').first().json;
const memory = $getWorkflowStaticData('global');
memory.skippedKeys = [...(memory.skippedKeys ?? []), ...post.keys].slice(-2000);

// Try the next story, but stop after three failed stories in one run.
if ($runIndex >= 2) return [];

return [{ json: { skipped: post.title, reason: $json.error?.message ?? $json.error ?? 'Instagram error' } }];
